'use strict';
let localAISession=null;
async function localAICall(action,payload){if(window.medDesktop){return {status:()=>medDesktop.localModelStatus(),start:()=>medDesktop.localModelStart(),stop:()=>medDesktop.localModelStop(),infer:()=>medDesktop.localModelInfer(payload)}[action]()}C.check(['127.0.0.1','localhost'].includes(location.hostname),'Automatic model setup is available in the desktop app or the local web launcher.');if(!localAISession){const r=await fetch('/local-model/session');C.check(r.ok,'Restart the updated local web launcher to enable AI setup');localAISession=(await r.json()).token}const r=await fetch('/local-model/'+action,{method:action==='status'?'GET':'POST',headers:{'Content-Type':'application/json','X-MedAnnotate-Session':localAISession},...(action==='infer'?{body:JSON.stringify(payload)}:{})});const result=await r.json();C.check(r.ok,result.error||'Local model request failed');return result}
function localAIView(){modal(`<h2>Local AI setup</h2><p>Prepare the trained model on this computer. First setup downloads a private runtime, model software and weights (allow several GB of disk space). Images stay on this computer. Later starts reuse the installed files.</p><p>This model suggests a mask inside a box you draw. It is not a validated automatic dental diagnosis or tooth-numbering model.</p><p id="localAIStatus" role="status">Checking…</p><button id="localAIStart" class="primary wide">Prepare and start local AI</button><button id="localAIStop" class="wide">Stop local AI</button><button id="localAIUse" class="wide" disabled>Use local AI on this image</button>`);let closed=false;const update=async()=>{try{const s=await localAICall('status');if(!closed&&$('localAIStatus')){$('localAIStatus').textContent=s.message;$('localAIStart').disabled=s.state==='setting-up'||s.state==='ready'||!s.supported;$('localAIUse').disabled=s.state!=='ready';if(!s.supported)$('localAIStatus').textContent='Automatic setup supports Apple Silicon, Windows x64 and Linux x64. Connect an external server on this platform.'}}catch(e){if(!closed&&$('localAIStatus'))$('localAIStatus').textContent=e.message}};void update();const timer=setInterval(()=>{if(!closed)void update()},2000);$('dialog').addEventListener('close',()=>{closed=true;clearInterval(timer)},{once:true});bind('localAIStart',async()=>{await localAICall('start');await update()});bind('localAIStop',async()=>{await localAICall('stop');await update()});bind('localAIUse',()=>{$('dialog').close();managedSliceModel=true;$('model').click()})}
bind('localAI',localAIView);
